fn numpy_insert<T>(arr: Vec<T>, idx: usize, value: T) -> Vec<T> {
    assert!(idx <= arr.len(), "idx must be in 0..=arr.len()");

    let mut result = Vec::with_capacity(arr.len() + 1);

    // Move elements before idx
    result.extend(arr[..idx].into_iter());
    // Insert value at idx
    result.push(value);
    // Move elements at/after idx (shifted by one)
    result.extend(arr[idx..].into_iter());

    result
}